"""Reproducible derivative-free search for the shared GRI formulation."""
import os,json,time,numpy as np
from gri_bench.api import load_instance,Experiment,save_design
I=load_instance(); E=Experiment(I)
B=I['bounds']; keys=('theta_a','relative_leak','ec50_mg_dl','hill_n','tau_min','theta_L')
def design(x): return {'mode':'responsive','parameters':dict(zip(keys,map(float,x)))}
def metrics(x):
 try:
  r=E.evaluate(design(x)); return r
 except Exception:return {'safe_tir':0,'feasible':False,'mean_tir':0,'max_trajectory_tbr70':100,'max_trajectory_tbr54':100,'minimum_glucose':-999}
def score(r):
 # Lexicographic-like smooth objective: safety dominates, then TIR.
 return r['mean_tir']-30*max(0,r['max_trajectory_tbr70']-3)-200*max(0,r['max_trajectory_tbr54']-.5)-3*max(0,55-r['minimum_glucose'])
